														`initial-${item.question.id}-${repeat}`,
														presentation(item.question, item.context),
														schemaFor(item.context),
														initialRun,
													);
										} catch (e) {
											for (const arm of arms)
												cells.push({
													...base,
													arm,
													status: "failed",
													error: String(e),
													inputTokens: 0,
													outputTokens: 0,
													latencyMs: 0,
												});
											checkpoint();
											continue;
										}
										for (const arm of [
											"baseline",
											...order(index, repeat),
										] as const) {
											let response:
												| Awaited<ReturnType<typeof review>>
												| undefined;
											try {
												response = await review(
													item.question,
													item.context,
													initial,
													arm,
													(stage, prompt, schema) =>
														call(
															`${stage === "initial" ? "audit" : "final-audit"}-${item.question.id}-${repeat}${stage === "initial" ? "" : `-${arm}`}`,
															prompt,
															schema,
															auditRun,
														),
													(prompt, schema) =>
														call(
															`repair-${item.question.id}-${repeat}-${arm}`,
															prompt,
															schema,
															arm === "role" ? roleRun : controlRun,
														),
												);
												const {
													raw,
													inputTokens,
													outputTokens,
													latencyMs,
													...details
												} = response;
												cells.push({
													...base,
													arm,
													status: "answered",
													raw,
													review: details,
													score: assess(item.question, item.context, arm, raw),
													inputTokens,
													outputTokens,
													latencyMs,
												});
											} catch (e) {
												cells.push({
													...base,
													arm,
													status: "failed",
													error: String(e),
													...(response ? { raw: response.raw } : {}),
													inputTokens:
														response?.inputTokens ?? initial.inputTokens,
													outputTokens:
														response?.outputTokens ?? initial.outputTokens,
													latencyMs: response?.latencyMs ?? initial.latencyMs,
												});
											}
											report.status = "running";
											checkpoint();
											console.log(
												`${cells.length}/${design.plannedEndpoints} ${item.question.id}/${repeat}/${arm}`,
											);
										}
									}
								}
								await Promise.all([worker(), worker()]);
							}, instructions.audit),
						instructions.revision,
					),
				instructions.revision,
			),
		instructions.initial,
	);
	report.codeUnchanged = codePaths.every(
		(f) => hash(readFileSync(resolve(root, f))) === digests[f],
	);
	report.status = !report.codeUnchanged
		? "invalidated-source-change"
		: cells.length !== design.plannedEndpoints
			? "incomplete"
			: cells.some((c) => c.status === "failed")
				? "completed-with-failures"
				: "completed";
	checkpoint();
	if (report.status !== "completed") process.exitCode = 1;
}
console.log(
	JSON.stringify({
		status: report.status,
		newCalls,
		reused,
		report: resolve(output, "report.json"),
	}),
);

