import {
	assess as sharedAssess,
	summarize as sharedSummary,
	type Cell as SharedCell,
} from "../operative-sources-comparison/results.ts";
import type { AnswerContext } from "../multi-source-comparison/world.ts";
import { arms, type Arm } from "./protocol.ts";
import type { SourceQuestion } from "./fixtures.ts";
export function assess(
	q: SourceQuestion,
	context: AnswerContext,
	_arm: Arm,
	raw: string,
) {
	const score = sharedAssess(q, context, "baseline", raw);
	return score;
}
export interface Cell extends Omit<SharedCell, "arm"> {
	arm: Arm;
	raw?: string;
	review?: Omit<
		Awaited<ReturnType<typeof import("./review.ts").review>>,
		"raw" | "inputTokens" | "outputTokens" | "latencyMs"
	>;
}
export function summarize(
	cells: readonly Cell[],
	questions: readonly SourceQuestion[],
) {
	function aggregate(qs: readonly SourceQuestion[]) {
		const byArm = Object.fromEntries(
			arms.map((arm) => [
				arm,
				sharedSummary(
					cells
						.filter((c) => c.arm === arm)
						.map((c) => ({ ...c, arm: "baseline" })),
					qs,
				).all.byArm.baseline!,
			]),
		);
		function pair(reference: Arm, candidate: Arm) {
			return sharedSummary(
				cells
					.filter((c) => c.arm === reference || c.arm === candidate)
					.map((c) => ({
						...c,
						arm: c.arm === reference ? "baseline" : "operative",
					})),
				qs,
			).all.pairs;
		}
		return {
			byArm,
			auditByArm: Object.fromEntries(
				arms.map((arm) => {
					const rows = cells.filter(
						(c) => c.arm === arm && qs.some((q) => q.id === c.questionId),
					);
					return [
						arm,
						{
							accepted: rows.filter((c) => c.review?.accepted).length,
							acceptedWrong: rows.filter(
								(c) => c.review?.accepted && !c.score?.primaryCorrect,
							).length,
							rejectedCorrect: rows.filter(
								(c) => c.score?.primaryCorrect && !c.review?.accepted,
							).length,
							newlyCaughtInitial: rows.filter(
								(c) =>
									c.review?.initialAudit.passed &&
									c.review?.initialRole?.passed === false,
							).length,
							finalRoleRejections: rows.filter(
								(c) => c.review?.finalRole?.passed === false,
							).length,
							reviews: rows.filter((c) => c.review?.repairAttempted).length,
						},
					];
				}),
			),
			pairs: {
				versusBaseline: pair("baseline", "role"),
				versusControl: pair("control", "role"),
				controlVersusBaseline: pair("baseline", "control"),
			},
		};
	}
	return {
		all: aggregate(questions),
		regression: aggregate(questions.filter((q) => q.suite === "regression")),
		unseen: aggregate(questions.filter((q) => q.suite === "unseen")),
		byPacket: Object.fromEntries(
			[...new Set(questions.map((q) => q.packet))].map((id) => [
				id,
				aggregate(questions.filter((q) => q.packet === id)),
			]),
		),
	};
}

import type { AnswerContext } from "../multi-source-comparison/world.ts";
import type { Question } from "../multi-source-comparison/fixtures.ts";
import { inspect, type Response } from "../audit-repair-comparison/review.ts";
export { inspect, type Response } from "../audit-repair-comparison/review.ts";
import {
	auditPrompt,
	auditSchema,
	validateAudit,
	type RoleAudit,
} from "./audit.ts";
import { presentation, schemaFor, type Arm } from "./protocol.ts";
export function reviewPrompt(
	q: Question,
	ctx: AnswerContext,
	raw: string,
	arm: "control" | "role",
	roleAudit: RoleAudit,
) {
	return JSON.stringify({
		task: "Review the previous answer against the original evidence and return a complete answer.",
		originalInput: JSON.parse(presentation(q, ctx)),
		previousAnswer: raw,
		structuralAudit: inspect(raw, ctx),
		...(arm === "role" ? { sourceRoleAudit: roleAudit } : {}),
	});
}
type Run = (prompt: string, schema: unknown) => Promise<Response>;
export async function review(
	q: Question,
	ctx: AnswerContext,
	initial: Response,
	arm: Arm,
	auditRun: (
		stage: "initial" | "final",
		prompt: string,
		schema: unknown,
	) => Promise<Response>,
	run: Run,
) {
	const initialAudit = inspect(initial.raw, ctx);
	if (arm === "baseline")
		return {
			...initial,
			initialAudit,
			finalAudit: initialAudit,
			initialRole: null,
			finalRole: null,
			repairAttempted: false,
			accepted: initialAudit.passed,
			outcome: "baseline" as const,
		};
	const first = await auditRun(
		"initial",
		auditPrompt(q, ctx, initial.raw),
		auditSchema,
	);
	const initialRole = validateAudit(first.raw, initial.raw, ctx);
	const cost = {
		inputTokens: initial.inputTokens + first.inputTokens,
		outputTokens: initial.outputTokens + first.outputTokens,
		latencyMs: initial.latencyMs + first.latencyMs,
	};
	if (initialAudit.passed && initialRole.passed)
		return {
			...initial,
			...cost,
			initialAudit,
			finalAudit: initialAudit,
			initialRole,
			finalRole: initialRole,
			repairAttempted: false,
			accepted: true,
			outcome: "unchanged" as const,
		};
	const revised = await run(
		reviewPrompt(q, ctx, initial.raw, arm, initialRole),
		schemaFor(ctx),
	);
	const finalAudit = inspect(revised.raw, ctx);
	const last = await auditRun(
		"final",
		auditPrompt(q, ctx, revised.raw),
		auditSchema,
	);
	const finalRole = validateAudit(last.raw, revised.raw, ctx);
	const accepted = finalAudit.passed && (arm === "control" || finalRole.passed);
	return {
		...revised,
		inputTokens: cost.inputTokens + revised.inputTokens + last.inputTokens,
		outputTokens: cost.outputTokens + revised.outputTokens + last.outputTokens,
		latencyMs: cost.latencyMs + revised.latencyMs + last.latencyMs,
		initialAudit,
		finalAudit,
		initialRole,
		finalRole,
		repairAttempted: true,
		accepted,
		outcome: accepted ? ("reviewed" as const) : ("rejected" as const),
	};
}

